import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] 份数 = new int[n];
        for (int i = 0; i < n; i++) {
            份数[i] = sc.nextInt();
        }

        Cat[] 一队 = new Cat[n];
        for (int i = 0; i < n; i++) {
            一队[i] = new Cat(份数[i]);
        }
        for (int i = 0; i < n; i++) {
            一队[i].start();
        }
        for (int i = 0; i < n; i++) {
            一队[i].join();
        }

        System.out.println("账本：" + Cat.账本 + " 条");
    }
}

class Cat extends Thread {
    static int 账本 = 0;

    int 要记;

    Cat(int 要记) {
        this.要记 = 要记;
    }

    public void run() {
        for (int i = 0; i < 要记; i++) {
            记一笔();
        }
    }

    static synchronized void 记一笔() {
        账本 = 账本 + 1;
    }
}
